<?php
require_once __DIR__.'/sales.php';
$kind=is_string($_GET['period']??null)?$_GET['period']:'month';$date=is_string($_GET['date']??null)?$_GET['date']:date('Y-m-d');
try{$range=salesPeriod($kind,$date);}catch(InvalidArgumentException $e){echo '<div class="alert error">'.e($e->getMessage()).'</div>';return;}
$s=salesTotals($range['start'],$range['end']);$receipts=salesReceipts($range['start'],$range['end']);$products=salesProducts($range['start'],$range['end']);
$unknown=query('SELECT COUNT(*) count,COALESCE(SUM(p.amount_cents),0) amount FROM payments p JOIN orders o ON o.id=p.order_id WHERE o.cancelled=0 AND p.paid_on IS NULL AND o.order_date BETWEEN ? AND ?',[$range['start'],$range['end']])->fetch();
?>
<section class="panel"><form method="get" class="sales-filters"><input type="hidden" name="page" value="sales"><div class="sales-filter"><label for="sales-period">보고 싶은 기간</label><select name="period" id="sales-period"><?php foreach(['week'=>'주간','month'=>'월간','year'=>'연간'] as $key=>$label): ?><option value="<?=$key?>" <?=$kind===$key?'selected':''?>><?=$label?></option><?php endforeach ?></select></div><div class="sales-filter"><label for="sales-date">기준 날짜</label><input type="date" id="sales-date" name="date" value="<?=e($date)?>" required></div><button class="button">통계 보기</button></form><p><strong><?=e($range['start'])?> ~ <?=e($range['end'])?></strong> · 주문 날짜 기준 · CAD</p><p class="hint">취소 주문·취소 수량을 제외하고 할인 후 금액을 표시합니다. 아직 전달·입금하지 않은 주문도 포함하므로 실제 입금액과 다를 수 있습니다.</p></section>
<div class="stats"><article><p>판매금액</p><strong><?=money($s['kimchi'])?></strong><span>할인 후 · 배달비 제외</span></article><article><p>주문 수</p><strong><?=$s['order_count']?><small>건</small></strong><span>고객 <?=$s['customer_count']?>명</span></article><article><p>전체 주문 금액</p><strong><?=money($s['total'])?></strong><span>배달비·기타 판매 포함</span></article><article class="warm"><p>이 기간 주문의 미입금</p><strong><?=money($s['unpaid'])?></strong><span>현재 남은 금액 기준</span></article></div>
<?php $comparison=salesThreeYears($kind,(int)substr($date,0,4));$cy=$comparison['year']; ?>
<section class="panel"><h2>최근 3년간 비교</h2><p class="hint">선택한 기준 날짜의 연도와 이전 2년 · 주문 날짜 기준 판매금액(할인 후, 배송비·기타수입 제외). 증감률은 바로 전년도 대비이며 비교 금액이 0이면 —로 표시합니다. 진행 중인 연도와 자료가 없는 기간은 해석에 유의하세요.</p><?php if($kind==='week'): ?><p class="hint">주차는 매년 1월 1일부터 7일 단위입니다. 52주에는 연말 남은 날짜를 모두 포함해 연간 합계와 일치시킵니다.</p><?php endif ?>
<div class="table-wrap"><table id="three-year-sales"><thead><tr><th><?=$kind==='week'?'주':($kind==='month'?'월':'기간')?></th><th><?=$cy?>년 금액</th><th>증감률</th><th><?=$cy-1?>년 금액</th><th>증감률</th><th><?=$cy-2?>년 금액</th></tr></thead><tbody>
<tr class="comparison-total"><th>합계</th><td><?=money($comparison['totals'][$cy])?></td><td><?=salesGrowth($comparison['totals'][$cy],$comparison['totals'][$cy-1])?></td><td><?=money($comparison['totals'][$cy-1])?></td><td><?=salesGrowth($comparison['totals'][$cy-1],$comparison['totals'][$cy-2])?></td><td><?=money($comparison['totals'][$cy-2])?></td></tr>
<?php foreach($comparison['rows'] as $row): $v=$row['amounts']; ?><tr><th><?=e($row['label'])?></th><td><?=money($v[$cy])?></td><td><?=salesGrowth($v[$cy],$v[$cy-1])?></td><td><?=money($v[$cy-1])?></td><td><?=salesGrowth($v[$cy-1],$v[$cy-2])?></td><td><?=money($v[$cy-2])?></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="panel"><h2>제품별 판매</h2><?php if(!$products): ?><p>이 기간에 등록된 제품 주문이 없습니다.</p><?php else: ?><div class="table-wrap"><table id="product-sales-table"><thead><tr><th scope="col" aria-sort="none"><button type="button" class="sort-button" data-sales-sort="name" data-sort-label="제품명">제품명 <span class="sort-icon" aria-hidden="true">↕</span></button></th><th scope="col">용량</th><th scope="col" aria-sort="none"><button type="button" class="sort-button" data-sales-sort="quantity" data-sort-label="판매 수량">판매 수량 <span class="sort-icon" aria-hidden="true">↕</span></button></th><th scope="col" aria-sort="descending"><button type="button" class="sort-button" data-sales-sort="amount" data-sort-label="판매금액">판매금액 <span class="sort-icon" aria-hidden="true">↓</span></button></th></tr></thead><tbody><?php foreach($products as $p): ?><tr data-name="<?=e($p['product_name'])?>" data-quantity="<?=(int)$p['quantity']?>" data-amount="<?=(int)$p['amount']?>"><td><?=e($p['product_name'])?></td><td><?=weight($p['weight_g'])?></td><td><?=(int)$p['quantity']?>개</td><td><?=money((int)$p['amount'])?></td></tr><?php endforeach ?></tbody></table></div><p class="hint">열 제목의 화살표를 누르면 오름차순·내림차순을 번갈아 정렬합니다. 같은 제품도 과거 용량이 다르면 구분합니다. 배달비·기타 판매·추가 수입은 제품 판매액에서 제외합니다.</p><?php endif ?></section>
<section class="panel"><h2>매출과 추가 수입 구분</h2><div class="table-wrap"><table><tbody><?php foreach(['판매금액'=>$s['kimchi'],'배송비'=>$s['delivery'],'기타수입'=>$s['other_sales']+$s['other_charges']+$s['additional_income']] as $label=>$amount): ?><tr><th><?=$label?><?=$label==='판매금액'?' · '.$s['order_count'].'건':''?></th><td><?=money($amount)?></td></tr><?php endforeach ?></tbody></table></div><p class="hint">추가 수입은 주문 청구액·판매금액에 다시 더하지 않습니다. 고객 예치금으로 처리하지 않습니다.</p></section>
<section class="panel"><h2>실제 입금일 기준</h2><p>입금일이 <?=e($range['start'])?> ~ <?=e($range['end'])?>인 기록: <strong><?=money($receipts['amount'])?></strong> · <?=$receipts['receipt_count']?>회</p><p>이 중 별도 추가 수입 <?=money($receipts['additional_income'])?></p><p class="hint">다른 기간에 주문한 제품의 입금도 포함합니다. 주문일 기준 위 통계와 합산하지 않습니다.</p><?php if($unknown['count']): ?><div class="notice">선택 기간에 주문한 과거 입금 중 날짜 미기록 <?=(int)$unknown['count']?>회 · <?=money((int)$unknown['amount'])?>가 있습니다. 실제 입금일을 알 수 없어 입금일 기준 통계에서는 제외했습니다.</div><?php endif ?></section>
